import { createServer } from 'vite';
import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';

const server = await createServer({ configFile: false, server: { middlewareMode: true, hmr: false, ws: false }, optimizeDeps: { noDiscovery: true }, appType: 'custom' });
try {
  // Capture before loading numerical modules. The bundled baseline generated by
  // the previous driver remains unchanged and recoverable at commit a47721f.
  const sourceHashes = {}, initializationHashes = {};
  for (const name of ['fireProtocol', 'fireProtocolRunner', 'model', 'source', 'thermodynamics', 'linear', 'remap']) sourceHashes[name] = createHash('sha256').update(await readFile(`src/coupled/${name}.ts`)).digest('hex');
  for (const name of ['solver', 'scenario', 'materials']) initializationHashes[name] = createHash('sha256').update(await readFile(`src/sim/${name}.ts`)).digest('hex');
  const generatorHash = createHash('sha256').update(await readFile('scripts/generate-fire-protocol.mjs')).digest('hex');
  const { version: applicationVersion } = JSON.parse(await readFile('package.json', 'utf8'));
  const { runFireProtocol } = await server.ssrLoadModule('/src/coupled/fireProtocolRunner.ts');
  let lastLogS = -Infinity;
  const cache = await runFireProtocol(JSON.parse(process.env.FIRE_OPTIONS || '{}'), {
    wallLimitS: Number(process.env.WALL_LIMIT_S || 300), treatmentDurationS: Number(process.env.FIRE_TREATMENT_SECONDS ?? 30), applicationVersion, mode: 'offline',
    onProgress: progress => {
      if (progress.elapsedS - lastLogS < 10) return;
      lastLogS = progress.elapsedS;
      console.log(JSON.stringify({ timeS: progress.timeS, phase: progress.phase, ...progress.frame.metrics, steps: progress.frame.ledger.steps, elapsedS: progress.elapsedS }));
    },
  });
  const report = { ...cache, sourceHashes, initializationHashes, generatorHash };
  const output = process.env.FIRE_REPORT || 'public/fire-sequence-cache.json';
  await writeFile(output, JSON.stringify(report) + '\n');
  const final = cache.frames.at(-1);
  console.log(JSON.stringify({ output, status: cache.status, stopReason: cache.stopReason, physicalTimeS: final.timeS, frames: cache.frames.length, elapsedS: cache.elapsedS, massResidualKg: final.ledger.massResidualKg, energyResidualJ: final.ledger.energyResidualJ }));
} finally { await server.close(); }
